# ===== BEGIN FILE: tmp/tests/hidden_eval.py =====
#!/usr/bin/env python3
"""Hidden evaluation for learned_cardinality_shift.  Runs as root in the verifier sandbox.

1. the candidate (/app/estimator.py) is imported and executed in a separate process running as
   `nobody`, inside a private work dir; the only thing it receives is the hidden queries'
   (tables, masks) in an npz, the only thing it returns is an npz with one float array.
2. labels are loaded only after the candidate process has exited.
3. this process writes /logs/verifier/reward.txt and metrics.json.
"""
import json
import os
import shutil
import subprocess
import sys
import tempfile
import time

import numpy as np

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
from scoring import raw_metrics, reward_from_raw  # noqa: E402

APP = os.environ.get("LCS_APP_DIR", "/app")
LOGDIR = os.environ.get("LCS_LOG_DIR", "/logs/verifier")
HIDDEN = os.path.join(HERE, "hidden", "hidden_queries.npz")
ANCHORS = os.path.join(HERE, "hidden", "anchors.json")
TIMEOUT_S = int(os.environ.get("LCS_TIMEOUT_S", "900"))
NOBODY = 65534

RUNNER = r'''
import importlib.util, os, sys, time
import numpy as np
app, qpath, opath = sys.argv[1], sys.argv[2], sys.argv[3]
sys.path.insert(0, app)
os.chdir(app)
with np.load(qpath, allow_pickle=False) as d:
    tables, masks = d["tables"].copy(), d["masks"].copy()
spec = importlib.util.spec_from_file_location("estimator", os.path.join(app, "estimator.py"))
mod = importlib.util.module_from_spec(spec)
sys.modules[spec.name] = mod
spec.loader.exec_module(mod)
t0 = time.time()
est = mod.CardinalityEstimator(os.path.join(app, "data"))
t1 = time.time()
out = est.estimate(tables, masks)
t2 = time.time()
out = np.asarray(out, dtype=np.float64).reshape(-1)
np.savez(opath, est=out, timing=np.array([t1 - t0, t2 - t1]))
'''


def _drop_privs():
    os.setgroups([])
    os.setgid(NOBODY)
    os.setuid(NOBODY)
    try:
        import resource
        resource.setrlimit(resource.RLIMIT_CORE, (0, 0))
    except Exception:
        pass


def kill_uid(uid):
    """Kill every process left behind by the candidate (daemonised children survive subprocess.run)."""
    import signal
    for _ in range(3):
        found = False
        for pid in os.listdir("/proc"):
            if not pid.isdigit():
                continue
            try:
                with open(f"/proc/{pid}/status") as f:
                    for line in f:
                        if line.startswith("Uid:"):
                            if int(line.split()[1]) == uid:
                                os.kill(int(pid), signal.SIGKILL)
                                found = True
                            break
            except (OSError, ValueError):
                pass
        if not found:
            return
        time.sleep(0.2)


def run_candidate(app_dir, tables, masks, timeout=TIMEOUT_S, log_path=None):
    """Returns (estimates (Q,), info dict).  Raises RuntimeError on failure."""
    as_root = os.geteuid() == 0
    work = tempfile.mkdtemp(prefix="lcs_cand_")
    try:
        qpath = os.path.join(work, "queries.npz")
        opath = os.path.join(work, "out.npz")
        rpath = os.path.join(work, "runner.py")
        np.savez(qpath, tables=tables, masks=masks)
        with open(rpath, "w") as f:
            f.write(RUNNER)
        if as_root:
            os.makedirs(LOGDIR, exist_ok=True)
            os.chown(LOGDIR, 0, 0)
            os.chmod(LOGDIR, 0o755)
            subprocess.run(["chmod", "-R", "a+rX", app_dir], check=False)
            for p in (work, qpath, rpath):
                os.chown(p, NOBODY, NOBODY)
            os.chmod(work, 0o700)
        env = {"PATH": "/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin", "HOME": work,
               "TMPDIR": work, "LANG": "C.UTF-8", "PYTHONDONTWRITEBYTECODE": "1"}
        logd = tempfile.mkdtemp(prefix="lcs_log_")  # root-only; candidate output goes to files, not pipes
        so, se = os.path.join(logd, "out"), os.path.join(logd, "err")
        t0 = time.time()
        try:
            with open(so, "w") as fo, open(se, "w") as fe:
                p = subprocess.run([sys.executable, "-I", rpath, app_dir, qpath, opath], cwd=work, env=env,
                                   timeout=timeout, stdout=fo, stderr=fe, stdin=subprocess.DEVNULL,
                                   preexec_fn=_drop_privs if as_root else None)
        except subprocess.TimeoutExpired as e:
            raise RuntimeError(f"candidate timed out after {timeout}s") from e
        finally:
            if as_root:
                kill_uid(NOBODY)
            wall = time.time() - t0
            out_txt = open(so, errors="replace").read()[-20000:]
            err_txt = open(se, errors="replace").read()[-20000:]
            shutil.rmtree(logd, ignore_errors=True)
            if log_path:
                with open(log_path, "w") as f:
                    f.write("=== stdout (tail) ===\n" + out_txt + "\n=== stderr (tail) ===\n" + err_txt)
        if p.returncode != 0:
            raise RuntimeError(f"candidate exited with code {p.returncode}: {err_txt[-2000:]}")
        if os.path.islink(opath) or not os.path.isfile(opath):
            raise RuntimeError("candidate produced no regular output file")
        fd = os.open(opath, os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0))
        with os.fdopen(fd, "rb") as fh, np.load(fh, allow_pickle=False) as d:
            est = np.asarray(d["est"], dtype=np.float64).reshape(-1).copy()
            timing = np.asarray(d["timing"], dtype=np.float64).reshape(-1)[:2].tolist() if "timing" in d.files else []
        if est.shape[0] != len(masks):
            raise RuntimeError(f"candidate returned {est.shape[0]} estimates for {len(masks)} queries")
        return est, {"wall_s": round(wall, 2), "init_s/estimate_s": [round(x, 2) for x in timing]}
    finally:
        shutil.rmtree(work, ignore_errors=True)


def write_out(reward, metrics):
    os.makedirs(LOGDIR, exist_ok=True)
    for fn in ("metrics.json", "reward.txt"):
        p = os.path.join(LOGDIR, fn)
        if os.path.lexists(p):
            if os.path.isdir(p) and not os.path.islink(p):
                shutil.rmtree(p)
            else:
                os.unlink(p)
    with open(os.path.join(LOGDIR, "metrics.json"), "w") as f:
        json.dump(metrics, f, indent=1)
    with open(os.path.join(LOGDIR, "reward.txt"), "w") as f:
        f.write(f"{reward:.6f}\n")


def main():
    if os.geteuid() == 0:
        os.chmod(HERE, 0o700)
    with np.load(HIDDEN, allow_pickle=False) as d:
        tables, masks = d["tables"].copy(), d["masks"].copy()
    os.makedirs(LOGDIR, exist_ok=True)
    try:
        est, info = run_candidate(APP, tables, masks, log_path=os.path.join(LOGDIR, "candidate.log"))
    except Exception as e:  # any failure of the candidate -> reward 0
        write_out(0.0, {"error": str(e)[-3000:], "reward": 0.0})
        print("candidate failed:", str(e)[-3000:])
        return
    with np.load(HIDDEN, allow_pickle=False) as d:
        H = {k: d[k].copy() for k in ["card", "split", "jtype"]}
    anchors = json.load(open(ANCHORS))
    raw = raw_metrics(est, H)
    reward, scores = reward_from_raw(raw, anchors)
    metrics = {"reward": reward, "group_scores": scores, "raw": raw, "info": info,
               "n_nonfinite": int((~np.isfinite(est)).sum())}
    write_out(reward, metrics)
    print(json.dumps({"reward": round(reward, 4), "group_scores": {k: round(v, 3) for k, v in scores.items()},
                      "mean_log_q": {k: round(v["mean_log_q"], 4) for k, v in raw.items()}, "info": info},
                     indent=1))


if __name__ == "__main__":
    main()

# ===== END FILE: tmp/tests/hidden_eval.py =====

# ===== BEGIN FILE: tmp/tests/rescore.py =====
#!/usr/bin/env python3
"""Offline re-scoring of finished runs with (possibly updated) anchors -- no re-running needed.

    python3 rescore.py metrics1.json [metrics2.json ...] [--anchors anchors.json]
                       [--set-best-agent]   # write the per-group best observed agent mean_log_q into anchors.json

metrics*.json are the files hidden_eval.py writes to /logs/verifier/metrics.json; the raw per-group
mean |log q| values in them are anchor independent.
"""
import argparse
import json
import os
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
from scoring import reward_from_raw  # noqa: E402


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("metrics", nargs="+")
    ap.add_argument("--anchors", default=os.path.join(HERE, "hidden", "anchors.json"))
    ap.add_argument("--set-best-agent", action="store_true")
    a = ap.parse_args()
    anchors = json.load(open(a.anchors))
    runs = []
    for p in a.metrics:
        m = json.load(open(p))
        if "raw" not in m:
            print(f"{p}: no raw metrics (failed run) -> 0")
            continue
        runs.append((p, m["raw"]))
    if a.set_best_agent and runs:
        for g in anchors["groups"]:
            anchors["groups"][g]["best_agent"] = min(r[g]["mean_log_q"] for _, r in runs)
        json.dump(anchors, open(a.anchors, "w"), indent=1)
        print(f"updated best_agent in {a.anchors}")
    for p, raw in runs:
        r, sc = reward_from_raw(raw, anchors)
        print(f"{r:.4f}  {p}  " + " ".join(f"{k}={v:.2f}" for k, v in sc.items()))


if __name__ == "__main__":
    main()

# ===== END FILE: tmp/tests/rescore.py =====

# ===== BEGIN FILE: tmp/tests/scoring.py =====
"""Pure scoring math shared by hidden_eval.py and rescore.py (no candidate code ever imports this)."""
import math

import numpy as np

SPLITS = ["mid", "tail"]
JT = ["O", "OC", "OP", "OCP"]


def log_qerror(est, card):
    est = np.nan_to_num(np.asarray(est, dtype=np.float64), nan=1.0, posinf=1e12, neginf=1.0)
    est = np.clip(est, 1.0, 1e12)
    card = np.maximum(np.asarray(card, dtype=np.float64), 1.0)
    return np.abs(np.log(est) - np.log(card))


def raw_metrics(est, H):
    """Per-group raw metrics (anchor independent).  H: dict with card, split, jtype."""
    lq = log_qerror(est, H["card"])
    out = {}
    for si, s in enumerate(SPLITS):
        for j, name in enumerate(JT):
            sel = (H["split"] == si) & (H["jtype"] == j)
            v = lq[sel]
            out[f"{s}/{name}"] = {"mean_log_q": float(v.mean()), "p50_q": float(np.exp(np.median(v))),
                                  "p90_q": float(np.exp(np.percentile(v, 90))), "n": int(sel.sum())}
        sel = H["split"] == si
        out[f"{s}/all"] = {"mean_log_q": float(lq[sel].mean()), "n": int(sel.sum())}
    return out


def group_score(L, L0, L1):
    if not np.isfinite(L):
        return 0.0
    if L <= L1:
        return 1.0
    if L >= L0:
        return 0.0
    return float(min(1.0, max(0.0, math.log(L0 / L) / math.log(L0 / L1))))


def reward_from_raw(raw, anchors):
    w = anchors["split_weights"]
    scores, total = {}, 0.0
    for s in SPLITS:
        vals = []
        for name in JT:
            g = anchors["groups"][f"{s}/{name}"]
            ref = g["oracle"] if g.get("best_agent") is None else min(g["oracle"], g["best_agent"])
            sc = group_score(raw[f"{s}/{name}"]["mean_log_q"], g["L0"], 0.8 * ref)
            scores[f"{s}/{name}"] = sc
            vals.append(sc)
        total += w[s] * float(np.mean(vals))
    return float(total), scores

# ===== END FILE: tmp/tests/scoring.py =====

