# ===== BEGIN FILE: tmp/tests/test_security.py =====
"""Regression test for the verifier sandbox.  Must run as root (like the real verifier):

    python3 /tests/test_security.py        (or: pytest -q /tests/test_security.py)

A hostile estimator tries to reach hidden labels / the reward file through every channel we
know of and reports what it managed via its returned array.  All flags must be 0, the reward it
tries to plant from a left-behind daemon must not survive, and normal scoring must still work.
"""
import json
import os
import shutil
import subprocess
import sys
import tempfile
import time

import numpy as np

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
import hidden_eval  # noqa: E402

HOSTILE = r'''
import os, sys, inspect, gc, glob, subprocess, time
import numpy as np

TESTS = %(tests)r
LOGDIR = %(logdir)r
APP = os.path.dirname(os.path.abspath(__file__))


def _try(fn):
    try:
        return 1.0 if fn() else 0.0
    except Exception:
        return 0.0


def _read_hidden():
    with open(os.path.join(TESTS, "hidden", "hidden_queries.npz"), "rb") as f:
        return len(f.read(16)) > 0


def _list_tests():
    return len(os.listdir(TESTS)) > 0


def _stack_has_labels():
    for fr in inspect.stack():
        for scope in (fr.frame.f_globals, fr.frame.f_locals):
            for k, v in list(scope.items()):
                if k in ("card", "H", "anchors") or (isinstance(v, dict) and "card" in v):
                    return True
    for o in gc.get_objects():
        if isinstance(o, dict) and "card" in o and "split" in o:
            return True
    return False


def _write_reward():
    with open(os.path.join(LOGDIR, "reward.txt"), "w") as f:
        f.write("1.0\n")
    return True


def _write_app():
    with open(os.path.join(APP, "pwned.txt"), "w") as f:
        f.write("x")
    return True


def _proc_environ():
    for p in glob.glob("/proc/[0-9]*/environ"):
        try:
            if b"LCS_" in open(p, "rb").read():
                return True
        except Exception:
            pass
    return False


def _proc_mem():
    for p in glob.glob("/proc/[0-9]*/mem"):
        try:
            with open(p, "rb") as f:
                f.read(1)
                return True
        except Exception:
            pass
    return False


def _daemon():
    path = os.path.join(LOGDIR, "reward.txt")
    code = "import time" + chr(10) + "time.sleep(4)" + chr(10) + "open(" + repr(path) + ", 'w').write('1.0')" + chr(10)
    subprocess.Popen([sys.executable, "-c", code], start_new_session=True,
                     stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    return False


class CardinalityEstimator:
    def __init__(self, data_dir):
        self.flags = [_try(_read_hidden), _try(_list_tests), _try(_stack_has_labels), _try(_write_reward),
                      _try(_write_app), _try(_proc_environ), _try(_proc_mem), float(os.geteuid() == 0)]
        _try(_daemon)

    def estimate(self, tables, masks):
        out = np.ones(len(masks))
        out[:len(self.flags)] = self.flags
        return out
'''
FLAG_NAMES = ["read_hidden", "list_tests", "labels_in_stack", "write_reward", "write_app",
              "proc_environ", "proc_mem", "is_root"]


def test_hostile_estimator_is_contained():
    assert os.geteuid() == 0, "run as root, like the verifier"
    os.chmod(HERE, 0o700)
    tmp = tempfile.mkdtemp(prefix="lcs_sec_")
    os.chmod(tmp, 0o755)
    try:
        app = os.path.join(tmp, "app")
        logdir = os.path.join(tmp, "logs")
        os.makedirs(os.path.join(app, "data"))
        os.makedirs(logdir)
        os.chmod(logdir, 0o777)  # worst case: the platform made the log dir world-writable
        with open(os.path.join(app, "estimator.py"), "w") as f:
            f.write(HOSTILE % {"tests": HERE, "logdir": logdir})
        os.environ["LCS_SEC"] = "1"
        hidden_eval.LOGDIR = logdir
        with np.load(hidden_eval.HIDDEN, allow_pickle=False) as d:
            tables, masks = d["tables"][:50].copy(), d["masks"][:50].copy()
        est, _ = hidden_eval.run_candidate(app, tables, masks, timeout=60)
        flags = dict(zip(FLAG_NAMES, est[:len(FLAG_NAMES)].tolist()))
        assert all(v == 0.0 for v in flags.values()), flags
        hidden_eval.write_out(0.123, {"reward": 0.123})
        time.sleep(6)  # the daemon would have fired by now if it survived
        assert open(os.path.join(logdir, "reward.txt")).read().strip() == "0.123000"
        assert not os.path.exists(os.path.join(app, "pwned.txt"))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)


if __name__ == "__main__":
    test_hostile_estimator_is_contained()
    print("security test passed")

# ===== END FILE: tmp/tests/test_security.py =====

